const a="geopolitica-umana-verso-la-teologia",o="geopolitica-umana/verso-la-teologia",e="https://precious-cassata-42205a.netlify.app/geopolitica-umana/verso-la-teologia",i="Verso la Teologia",d="",l="Tre card per esplorare il confine che si sfoglia tra analisi geopolitica e riflessione teologica, la possibilità di una teologia politica radicata nell’antropologia dei popoli, e una griglia operativa per applicare il metodo fabbriano alle comunità.",t="geopolitica-umana",r="geopolitica-umana",n=[{type:"p",role:"p",runs:[{t:"Geopolitica Umana · Dalla lente alla soglia"}]},{type:"h",level:1,runs:[{t:"Verso la "},{t:"Teologia",i:!0}],role:"p"},{type:"p",role:"p",runs:[{t:"Tre card per esplorare il confine che si sfoglia tra analisi geopolitica e riflessione teologica, la possibilità di una teologia politica radicata nell’antropologia dei popoli, e una griglia operativa per applicare il metodo fabbriano alle comunità."}]},{type:"p",role:"p",runs:[{t:"Introduzione"}]},{type:"h",level:2,runs:[{t:"Dalla geopolitica umana verso la teologia"}],role:"p"},{type:"p",role:"p",runs:[{t:"La geopolitica umana di Dario Fabbri descrive la meccanica del destino umano: come i popoli nascono, vivono, combattono e muoiono. La teologia ne indaga il senso. Tra le due non c’è opposizione, ma una soglia — e il pensiero di Fabbri, forse senza saperlo, conduce dritto a quella soglia."}]},{type:"p",role:"p",runs:[{t:"Fabbri fa tabula rasa delle spiegazioni superficiali. Lascia l’uomo «nudo», di fronte alle sue angosce, alla sua mortalità, al suo bisogno disperato di appartenenza. Porta la sua analisi fino al limite estremo dell’immanenza terrestre e lì si ferma. Ma proprio lì, su quella soglia, "},{t:"inizia la teologia",b:!0},{t:"."}]},{type:"p",role:"p",runs:[{t:"Non si tratta di «aggiungere Dio» alla geopolitica. Si tratta di riconoscere che l’analisi dei popoli — della loro paura, del loro desiderio di eternità, del loro bisogno di appartenenza — apre naturalmente una domanda che trascende la materia. La geopolitica umana ci porta fino al limite estremo del pensabile; da lì si può solo guardare oltre, o tornare indietro. Questo è il passo che chiamiamo "},{t:"verso la teologia",b:!0},{t:"."}]},{type:"p",role:"p",runs:[{t:"«La geopolitica descrive la prigione. La teologia apre la porta. Il MetaHistoria sta sulla soglia.»"}]},{type:"p",role:"p",runs:[{t:"Qui sotto quattro card, quattro percorsi possibili per chi voglia esplorare questo passaggio: il confine che si sfoglia tra i due sguardi, la possibilità di una teologia geopolitica, una griglia operativa per analizzare le comunità con gli occhi di Fabbri, e un dossier completo sul ritorno del sacro nella storia globale."}]},{type:"p",role:"p",runs:[{t:"Card 1 ☘ Il confine che si sfoglia Dalla geopolitica alla teologia: la soglia tra la descrizione spietata di ciò che accade e la domanda su ciò che significa. Il percorso del MetaHistoria attraverso le tre lenti. →   Card 2 ☀ Per una teologia politica Quattro carotaggi teologici nella sala macchine dello Stato: dal Peccato Originale al Katechon, passando per Babele e l’idolatria dell’ideologia. →   Card 3 ★ Griglia di analisi geopolitica Asse biologico, psicologico, geografico e strategico: una griglia operativa per sezionare ogni comunità con il metodo di Dario Fabbri, fino alla soglia teologica. →   Card 4 ✡ Il sacro non ? mai uscito Dossier di sei intrecci esemplari tra fede e potenza, i numeri della religione nel mondo, e una cronologia del ritorno del sacro nella storia globale. →"}]}],s=[{label:"← Precedente",title:"Il destino dei popoli — L'opera",href:"/geopolitica-umana/destino-dei-popoli-libro"},{label:"Home Lente →",title:"Geopolitica Umana",href:"/geopolitica-umana/"}],p=["D. Fabbri, Geopolitica umana (2023)","D. Fabbri, Sotto la pelle del mondo (2024)","D. Fabbri, Il destino dei popoli (Gribaudo, 2025)","R. Niebuhr, L’uomo morale e la società immorale (1932)","Agostino d’Ippona, La Città di Dio (426 d.C.)"],c={blocks:11,chars:2592,hash:"d3ac87329f914f78b12ef5f045d0de4435fa27e6f331511a0f623834f10500f3"},g={id:a,slug:o,sourceUrl:e,title:i,kicker:"",lede:l,category:t,parentId:r,blocks:n,prevNext:s,references:p,stats:c};export{n as blocks,t as category,g as default,a as id,d as kicker,l as lede,r as parentId,s as prevNext,p as references,o as slug,e as sourceUrl,c as stats,i as title};
